from preserve import R,V2,V1,sha,dump,inventory
import json,statistics
def main():
    reg=json.loads((R/'REGISTRATION.json').read_text());drift=[p for p,h in reg['files'].items() if sha(R/p)!=h];preserved=json.loads((R/'preservation/V2_MANIFEST.json').read_text());v2_same=inventory(V2)==preserved['files'];archive_same=sha(R/'preservation/v2-failed-qualification.zip')==preserved['archive_sha256'];v1_manifest=json.loads((V2/'preservation/FAILED_RUN_MANIFEST.json').read_text());v1_same=inventory(V1)==v1_manifest['files']
    banks=json.loads((R/'inputs/banks.json').read_text());fresh={}
    for arm,docs in banks['hebrew'].items():
        v2=json.loads((R/'inputs/v2-banks.json').read_text());oldids={i for d in v2['hebrew'][arm] for i in d['test_segment_ids']};parents=[p['parent'] for d in docs for p in d['parents']];cal={p['parent'] for d in docs if d['bank']=='calibration' for p in d['parents']};confirm={p['parent'] for d in docs if d['bank']=='confirmation' for p in d['parents']}
        fresh[arm]=dict(selected_parents=len(parents),unique_parents=len(set(parents)),v2_parent_overlap=len(set(parents)&oldids),calibration_confirmation_parent_overlap=len(cal&confirm));assert len(parents)==640 and len(set(parents))==640 and not (set(parents)&oldids) and not (cal&confirm)
    arms={a:json.loads((R/'results'/a/'RESULT.json').read_text()) for a in ['tanakh','medieval']};g0=not drift and v2_same and archive_same and v1_same;blocks=[]
    for arm,r in arms.items():
        for dimension in ['SCORER','DECODER','OBJECTIVE','SEARCH']:
            if r[dimension]!='PASS':blocks.append(f'{arm}.{dimension}')
    blocks.append('FRESH_C17_UNAVAILABLE')
    if not g0:blocks.append('PRESERVATION_OR_FREEZE_FAILED')
    result=dict(status='NOT_QUALIFIED',G0=g0,dimensions={a:{k:r[k] for k in ['SCORER','DECODER','OBJECTIVE','SEARCH','FRESH_C17']} for a,r in arms.items()},blocking_conditions=blocks,v2_preserved=v2_same,v1_preserved=v1_same,archive_matches=archive_same,registered_file_drift=drift,freshness=fresh,ZL='CLOSED',actual_C11='CLOSED',new_ZL_scores=0,new_actual_C11_scores=0,C17_rescored=False,retuned=False,registration_sha256=sha(R/'REGISTRATION.json'))
    dump(R/'QUALIFICATION.json',result)
    lines=['# C16-KH v3: EOS repair and separated qualification','',
    '**Full qualification: NOT QUALIFIED. ZL and actual C11 remain CLOSED.** No new manuscript scores. Fresh C17 evidence is unavailable: the user confirms no unused source or additional writers. Noise, splitting, resampling or relabeling old writers does not supply new human evidence.','',
    '## Preservation and frozen repair','',f"V2 preserved: {v2_same}; archived {len(preserved['files'])} files, SHA256 `{preserved['archive_sha256']}`. V1 preserved: {v1_same}. Registered v3 code/input/protocol drift: {len(drift)}. Both failed runs and sealed keys remain untouched.",'',
    'The sole production algorithm change builds ctx(a,b) from actual emitted trigram prefixes. The extra terminal (word,EOS) pair is excluded. The same repair applies to word and alphagram LMs. The tests compare all observed nonterminal event probabilities and interpolation weights to v2: this repairs terminal normalization, not the earlier weak discrimination or limited key search. Search budgets, candidate lists, normalization, all24 variants and word-slot rank are unchanged.','',
    'Scorer tests use gold surface words and matched fresh nulls, with NO decoder or key fitting. Decoder accuracy uses the true mapping separately. OBJECTIVE checks whether the combined key objective prefers the true key; SEARCH checks whether the unchanged blind search finds it. Fitted external-null maxima involve search and are diagnostic only; they never decide the SCORER status.','',
    '| Arm | Math | Corruption | Order | Null operating point | SCORER | DECODER | OBJECTIVE | SEARCH |','|---|---|---|---|---|---|---|---|---|']
    for a,r in arms.items():lines.append('| '+a+' | '+' | '.join('PASS' if r['scorer_gates'][k] else 'FAIL' for k in ['MATH','CORRUPTION','ORDER','NULL'])+' | '+' | '.join(r[k] for k in ['SCORER','DECODER','OBJECTIVE','SEARCH'])+' |')
    for a,r in arms.items():
        lines+=['',f'## {a}','',f"Fresh parents/windows: {fresh[a]['selected_parents']}; v2 parent overlap: {fresh[a]['v2_parent_overlap']}; calibration/confirmation parent overlap: {fresh[a]['calibration_confirmation_parent_overlap']}. Forty calibration and forty confirmation documents, eight windows per document."]
        for m in r['math']['models']:lines+=['',f"{m['model']} LM: ctx exactly equals outgoing counts={m['ctx_exactly_outgoing']}; normalized distribution max error={m['max_normalization_error']:.3g}; {m['observed_events_checked']:,} nonterminal events checked against v2, max log-probability difference={m['max_v2_nonterminal_log_delta']:.3g}."]
        c=r['corruption'];o=r['ordering'];d=r['decoder'];lines+=['',f"Gold-word scorer: original beats quarter-UNKNOWN {c['original_beats_quarter']}/{c['n']}, all-UNKNOWN {c['original_beats_all']}/{c['n']}; all-UNKNOWN top3 selections={c['UNKNOWN_top3']}, document wins={c['UNKNOWN_docwins']}.",'',f"Order discrimination: {o['wins']} wins, {o['losses']} losses, {o['ties']} ties, gate count {o['half_tie_wins']}/40; exact sign tail with ties omitted={o['exact_sign_tail']:.6g}. Within-word gold-token invariance={o['within_word_equal']}.",'',
        '| Raw matched null | Positive exceed /40 | Null exceed /40 | Null 95% Wilson interval | AUC |','|---|---:|---:|---|---:|']
        for n in r['null_operating_point']:lines.append(f"| {n['family']} | {n['positive_exceed']} | {n['false_positive']} | {n['false_positive_interval'][0]:.1%}–{n['false_positive_interval'][1]:.1%} | {n['AUC']:.3f} |")
        lines+=['',f"Separate known-key decoder: IV word accuracy={d['IV_accuracy']:.2%}, all-token accuracy={d['all_token_accuracy']:.2%}, within-word candidate/output/score invariance={d['within_word_equal']}.",'',f"Separate blind search: median alphagram recovery={r['search_median']:.2%}, minimum={r['search_minimum']:.2%}. Individual recoveries: "+', '.join(f"{x['alphagram_recovery']:.2%}" for x in r['cipher_cases'])+'. True-key-vs-100-wrong-key wins: '+', '.join(str(x['wrong_keys_lower']) for x in r['cipher_cases'])+'.', '',
        'When the true-key objective wins but fitted keys have poor recovery and lower objective, the residual is a search failure. It cannot be counted as a scorer failure or fixed by quietly adding search starts. Actual C1/C9 fitted-null score tables explicitly mark search involvement.']
    lines+=['','## Freshness limits and holds','',
    'Freshness means disjoint qualification source segments/positions and new null draws, not new corpus editions. V2-selected parents were excluded entirely before selecting one deterministic <=32-word contiguous window per remaining segment. Exact v2-window/training-segment matches and duplicate windows were excluded. V1 aggregate held-out means, same-work training, common-phrase overlap and artificial window boundaries remain disclosed limitations. No scoring influenced window selection.','',
    'C1 diagnostic pages exclude all40 used by v2, but had v1 aggregate exposure. C9 uses fresh seeded draws of the fixed legacy schematic grille, with fresh Hebrew word-slot geometry. Neither is a substitute for fresh human C17. No C17 document was rescored. Hebrew-only within-word shuffles test the C11 equality without admitting actual Voynich-derived C11.','',
    'The original-task hold cannot be lifted while required C17 evidence is unavailable, even if a narrower scorer or objective dimension passes. Other failed dimensions also remain failures. No new ZL runner was created or invoked. No threshold, candidate, variant, search budget or holdout was revised after these outcomes. The new confirmation bank is now exposed and cannot become fresh evidence for later tuning.','',
    'Frozen rules and inputs: PROTOCOL.md, REGISTRATION.json, inputs/banks.json. Detailed receipts: results/<arm>/RESULT.json, SCORER_DECODER.json, MATH.json, full variant-source.csv and separate raw-scorer/decoder/fitted-external-null tables, cipher cases and gold/fitted key objectives. Preservation: preservation/V2_MANIFEST.json and v2-failed-qualification.zip. No human ratings, Hebrew identification, semantic or translation claims.']
    (R/'REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf8');print(json.dumps(result,indent=2))
if __name__=='__main__':main()
